const lookUpParticipantCards = `-- name: LookUpParticipantCards :many
SELECT r.id AS rally_id, r.title AS rally_title, c.token AS card_token, c.participant_name, c.world, c.completed,
       CAST(COALESCE(g.title, '') AS TEXT) AS garapon_title,
       CAST(COALESCE(gp.max_draws, 0) - COALESCE((SELECT COUNT(*) FROM garapon_draws d WHERE d.player_id = gp.id), 0) AS INTEGER) AS draws_left
FROM stamp_rally_cards c
JOIN stamp_rallies r ON r.id = c.rally_id
LEFT JOIN garapon_players gp ON gp.stamp_card_id = c.id
LEFT JOIN garapons g ON g.id = gp.garapon_id AND g.status = 'open'
WHERE r.status = 'open' AND (
    (c.participant_name = ?1 COLLATE NOCASE AND c.world = ?2 COLLATE NOCASE)
    OR (c.world = '' AND c.participant_name IN (?1, ?3) COLLATE NOCASE)
)
ORDER BY r.created_at DESC, r.id DESC
`

type LookUpParticipantCardsParams struct {
	Name  string
	World string
	Label string
}

type LookUpParticipantCardsRow struct {
	RallyID         int64
	RallyTitle      string
	CardToken       string
	ParticipantName string
	World           string
	Completed       int64
	GaraponTitle    string
	DrawsLeft       int64
}

// The cards held under a name and world, ignoring case, in rallies still open, with the
// draws left on the drawing link issued with each. The drawing token is deliberately not
// selected: this is keyed on a character name, which is public, and a draw can't be
// undone. A card with no world (staff issued it, or the world was never known) is found
// by the name alone, or by the whole "Name @ World" label.
func (q *Queries) LookUpParticipantCards(ctx context.Context, arg LookUpParticipantCardsParams) ([]*LookUpParticipantCardsRow, error) {
	rows, err := q.db.QueryContext(ctx, lookUpParticipantCards, arg.Name, arg.World, arg.Label)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*LookUpParticipantCardsRow{}
	for rows.Next() {
		var i LookUpParticipantCardsRow
		if err := rows.Scan(
			&i.RallyID,
			&i.RallyTitle,
			&i.CardToken,
			&i.ParticipantName,
			&i.World,
			&i.Completed,
			&i.GaraponTitle,
			&i.DrawsLeft,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

